#include "AudioRing.h"
#include <stdlib.h>
#include <stdatomic.h>
#include <math.h>
struct AudioRing {float *data;uint32_t capacity;_Atomic uint64_t read,write,overflows,underruns;};
AudioRing *ring_create(uint32_t n){if(n<2||n>1048576)return NULL;AudioRing*r=calloc(1,sizeof(*r));if(!r)return NULL;r->data=calloc((size_t)n*2,sizeof(float));if(!r->data){free(r);return NULL;}r->capacity=n;atomic_init(&r->read,0);atomic_init(&r->write,0);atomic_init(&r->overflows,0);atomic_init(&r->underruns,0);return r;}
void ring_destroy(AudioRing*r){if(r){free(r->data);free(r);}}
uint32_t ring_available(const AudioRing*r){uint64_t rd=atomic_load_explicit(&r->read,memory_order_acquire),w=atomic_load_explicit(&r->write,memory_order_acquire);return w>=rd?(uint32_t)fmin(w-rd,r->capacity):0;}
static bool layout(const AudioBufferList*b){return b&&((b->mNumberBuffers==1&&b->mBuffers[0].mNumberChannels==2&&b->mBuffers[0].mData)||(b->mNumberBuffers==2&&b->mBuffers[0].mNumberChannels==1&&b->mBuffers[1].mNumberChannels==1&&b->mBuffers[0].mData&&b->mBuffers[1].mData));}
uint32_t ring_write(AudioRing*r,const AudioBufferList*b){if(!r||!layout(b))return 0;bool planar=b->mNumberBuffers==2;uint32_t frames=b->mBuffers[0].mDataByteSize/(sizeof(float)*(planar?1:2));if(planar){uint32_t other=b->mBuffers[1].mDataByteSize/sizeof(float);if(other<frames)frames=other;}uint64_t w=atomic_load_explicit(&r->write,memory_order_relaxed),rd=atomic_load_explicit(&r->read,memory_order_acquire);if(frames>r->capacity-(w-rd)){atomic_fetch_add_explicit(&r->overflows,frames,memory_order_relaxed);return 0;}const float*l=b->mBuffers[0].mData,*rr=planar?b->mBuffers[1].mData:l;for(uint32_t i=0;i<frames;i++){size_t at=((w+i)%r->capacity)*2;float a=l[planar?i:i*2],c=rr[planar?i:i*2+1];r->data[at]=isfinite(a)?a:0;r->data[at+1]=isfinite(c)?c:0;}atomic_store_explicit(&r->write,w+frames,memory_order_release);return frames;}
uint32_t ring_read(AudioRing*r,uint32_t n,AudioBufferList*b){if(!r||!layout(b))return 0;bool planar=b->mNumberBuffers==2;uint32_t cap=b->mBuffers[0].mDataByteSize/(sizeof(float)*(planar?1:2));if(planar){uint32_t other=b->mBuffers[1].mDataByteSize/sizeof(float);if(other<cap)cap=other;}if(n>cap)n=cap;uint64_t rd=atomic_load_explicit(&r->read,memory_order_relaxed),w=atomic_load_explicit(&r->write,memory_order_acquire);uint32_t take=(uint32_t)fmin(n,w-rd);float*l=b->mBuffers[0].mData,*rr=planar?b->mBuffers[1].mData:l;for(uint32_t i=0;i<n;i++){size_t at=((rd+i)%r->capacity)*2;l[planar?i:i*2]=i<take?r->data[at]:0;rr[planar?i:i*2+1]=i<take?r->data[at+1]:0;}atomic_store_explicit(&r->read,rd+take,memory_order_release);if(take<n)atomic_fetch_add_explicit(&r->underruns,n-take,memory_order_relaxed);return take;}
uint64_t ring_overflows(const AudioRing*r){return atomic_load_explicit(&r->overflows,memory_order_relaxed);}
uint64_t ring_underruns(const AudioRing*r){return atomic_load_explicit(&r->underruns,memory_order_relaxed);}
